query:
LOAD CSV WITH HEADERS FROM
'https://raw.githubusercontent.com/ren2335/engine-kg/main/refer_restructured_mod.csv'
AS row

MERGE (a:Node {
    name: row.源节点名称,
    type: row.源节点标签
})

MERGE (b:Node {
    name: row.目标节点名称,
    type: row.目标节点标签
})

MERGE (a)-[:RELATION {
    relation: row.关系类型
}]->(b);

LOAD CSV WITH HEADERS FROM
'https://raw.githubusercontent.com/ren2335/engine-kg/main/cross_restructured_mod.csv'
AS row

MERGE (a:Node {
    name: row.源节点,
    type: row.源标签
})

MERGE (b:Node {
    name: row.目标节点,
    type: row.目标标签
})

MERGE (a)-[:CROSS_RELATION {
    relation: row.关系类型
}]->(b);

CREATE (:Layer {name:"Component Layer"});
CREATE (:Layer {name:"Parameter Layer"});
CREATE (:Layer {name:"Equation Layer"});
CREATE (:Layer {name:"BoundaryCondition Layer"});

MATCH (n:Node)
WHERE n.type = "Component"
SET n:Component;

MATCH (n:Node)
WHERE n.type = "Parameter"
SET n:Parameter;

MATCH (n:Node)
WHERE n.type = "Equation"
SET n:Equation;

MATCH (n:Node)
WHERE n.type = "BoundaryCondition"
SET n:BoundaryCondition;

MATCH (n:Component)
REMOVE n:Node;
MATCH (n:Parameter)
REMOVE n:Node;
MATCH (n:Equation)
REMOVE n:Node;
MATCH (n:BoundaryCondition)
REMOVE n:Node;

MATCH (n)-[r]->(m)
RETURN n,r,m
LIMIT 300;
